import {PROVIDERS,HOUR,DAY,uid,esc,countdown,isExpired,isDue,percent,remaining,available,resetCount,rankAccounts,monthlyCost,advanceReset,validateAccount,validateBackup} from './domain.js';
import {isNative,shareBackup,openProvider} from './native.js';
import {setupGoogleSync} from './sync-ui.js';
import {loadPreferences,openSetup,guidePage,PREFS_KEY} from './setup.js';
let preferences=loadPreferences();
const KEY='orbit.workspace.v1';
const $=s=>document.querySelector(s);
let state,storageError='';
try{const saved=localStorage.getItem(KEY);state=saved?validateBackup(JSON.parse(saved)):{version:1,demo:false,accounts:[],history:[]};}catch{state={version:1,demo:false,accounts:[],history:[]};storageError='Saved data could not be read. Export a recovery copy in Settings before making changes.';}
let view='dashboard',filter='All accounts',query='',task='All work',installPrompt=null,editingId=null,pendingImport=null;
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',accounts:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',calendar:'M4 5h16v16H4z M16 3v4 M8 3v4 M4 11h16',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',check:'m5 12 4 4L19 6',shield:'M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6z m-4 9 3 3 5-6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M4 16v5h16v-5',close:'m6 6 12 12 M6 18 18 6',edit:'m16 3 5 5-12 12-6 1 1-6z M14 5l5 5',star:'m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.3-5.7-3-5.7 3 1.1-6.3L2.8 9.7l6.4-.9z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',wallet:'M3 5h17v15H3z M3 5V3h14 M15 11h6v5h-6z',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2',logout:'M9 3H3v18h6 M10 12h11 m-5-5 5 5-5 5',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.grid}"/></svg>`;
const money=(v,c=preferences.currency)=>new Intl.NumberFormat(undefined,{style:'currency',currency:c,maximumFractionDigits:v%1?2:0}).format(v);
const formatDate=d=>d?new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Not set';
const time=d=>d?new Date(d).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}):'Not set';
const timer=d=>`<span data-countdown="${esc(d||'')}">${countdown(d)}</span>`;
const providerIcon=a=>`<div class="provider-icon" style="--provider:${PROVIDERS[a.provider].color}">${PROVIDERS[a.provider].glyph}</div>`;
const empty=(title,desc,action='')=>`<div class="empty">${icon('spark')}<h3>${title}</h3><p>${desc}</p>${action}</div>`;
const addButton=`<button class="btn primary" data-action="add">${icon('plus')} Add account</button>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function persist(){if(state.demo)return;try{if(storageError)throw Error(storageError);localStorage.setItem(KEY,JSON.stringify(state));googleSync?.changed();return true;}catch{toast('Could not save locally. Export a backup before closing.');return false;}}
function log(text){state.history.unshift({at:new Date().toISOString(),text});state.history=state.history.slice(0,5000);}
function commit(text){log(text);const saved=persist();render();if(saved!==false)toast(text);}
function totals(){const totals={};for(const a of state.accounts){const cost=monthlyCost(a);if(cost)totals[a.currency]=(totals[a.currency]||0)+cost;}return Object.entries(totals).map(([c,v])=>money(v,c));}
function nextEvents(){return state.accounts.flatMap(a=>[...a.windows.filter(w=>w.nextReset).map(w=>({a,w,date:w.nextReset,type:'reset',label:`${w.label} reset`,desc:w.mode==='fixed'?'Scheduled · confirm when available':'Rolling window · estimated'})),...(a.renewAt?[{a,date:a.renewAt,type:'renewal',label:a.autoRenew?'Subscription renewal':'Billing date',desc:`${a.tier} · ${a.status}`}]:[]),...(a.expiresAt?[{a,date:a.expiresAt,type:'expiry',label:a.status==='Trial'?'Trial ends':'Subscription expires',desc:'Check access before continuing'}]:[])]).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));}
function nav(){return [['dashboard','grid','Overview'],['accounts','accounts','Accounts'],['recommend','spark','Use next'],['schedule','calendar','Calendar'],['history','history','Activity'],['guide','info','Setup guide'],['settings','settings','Settings']].map(([id,i,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='accounts'?`<span class="count">${state.accounts.length}</span>`:''}</button>`).join('');}
function render(){
 const titles={dashboard:['Your AI, in balance.','A little clarity for all the intelligence in your life.'],accounts:['Every account. One home.','Know what’s available, what resets next, and what needs attention.'],recommend:['Make your next move.','A practical shortlist based on the limits you have recorded.'],schedule:['A clearer view of what’s next.','Usage resets, renewals, and trial endings — all on your timeline.'],history:['Your activity, remembered.','A local record of account changes and usage updates.'],guide:['A good place to start.','Set up, track, and protect your workspace.'],settings:['Make Orbit yours.','Your preferences, your data, your devices.']};
 const [title,subtitle]=titles[view];
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a href="#" class="brand" data-view="dashboard"><img src="./icon.svg" alt="">orbit<span class="spacer"></span><small>Beta v1</small></a><p class="nav-label">WORKSPACE</p><nav class="nav" aria-label="Main navigation">${nav()}</nav><div class="sidebar-bottom"><div class="local-card"><strong>${icon('shield')} Yours. On this device.</strong>Offline by design.<br>No passwords needed.</div><div class="profile"><div class="avatar">ME</div><div><strong>${esc(preferences.workspaceName)}</strong><small>Stored on this device</small></div></div></div></aside><main><header class="topbar"><div class="breadcrumb">Workspace <span style="padding:0 12px;color:#555b66">/</span> <span style="color:var(--text)">${({dashboard:'Overview',recommend:'Use next',schedule:'Calendar'})[view]||view.charAt(0).toUpperCase()+view.slice(1)}</span></div><a class="mobile-brand" data-view="dashboard" href="#"><img src="./icon.svg" alt="">orbit</a><div class="top-actions"><span class="date">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span><span class="status"><span class="dot"></span><span id="network-label">${navigator.onLine?'Local workspace':'Working offline'}</span></span><button class="icon-btn" data-action="theme" aria-label="Toggle light and dark theme">${icon('sun')}</button></div></header><div class="page-header"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${['dashboard','accounts'].includes(view)?addButton:''}</div>${storageError?`<div class="notice">${esc(storageError)}</div>`:''}<div id="page">${({dashboard:dashboard,accounts:accountsPage,recommend:recommendPage,schedule:schedulePage,history:historyPage,settings:settingsPage,guide:guidePage})[view]()}</div><footer class="app-footer"><span>${icon('shield')} Offline-first · Optional Google sync · No analytics</span><span>Made for a more intentional workflow. &nbsp; Orbit Beta v1</span></footer></main></div>`;
 googleSync?.render();
}
function dashboard(){
 const availableCount=state.accounts.filter(a=>available(a)).length;
 const due=state.accounts.flatMap(a=>a.windows).filter(w=>w.nextReset).sort((a,b)=>Date.parse(a.nextReset)-Date.parse(b.nextReset))[0];
 const spend=totals();
 const upcoming=state.accounts.filter(a=>a.expiresAt&&Date.parse(a.expiresAt)-Date.now()<7*DAY&&!isExpired(a)).length;
 return `${state.accounts.length?'':gettingStarted()}<section class="stats" aria-label="Workspace summary"><div class="stat"><div class="stat-title">Total accounts ${icon('accounts')}</div><div class="stat-number">${state.accounts.length}<small> across ${new Set(state.accounts.map(a=>a.provider)).size} providers</small></div><div class="stat-note green">${availableCount} ready for your next idea</div></div><div class="stat"><div class="stat-title">Ready to use ${icon('spark')}</div><div class="stat-number">${availableCount}<small> / ${state.accounts.length}</small></div><div class="stat-note">Based on recorded usage</div></div><div class="stat"><div class="stat-title">Next reset ${icon('clock')}</div><div class="stat-number" style="font-size:25px">${due?timer(due.nextReset):'—'}</div><div class="stat-note">${due?esc(due.label):'Add a usage window to begin'}</div></div><div class="stat"><div class="stat-title">Monthly subscriptions ${icon('wallet')}</div><div class="stat-number money" style="${spend.length>1?'font-size:19px':''}">${spend.join(' + ')||money(0)}<small> / mo</small></div><div class="stat-note">${upcoming?`${upcoming} trial or subscription ending soon`:'Annual plans averaged monthly'}</div></div></section>${hero()}<section><div class="section-heading"><h2>Your accounts <span>${state.accounts.length}</span></h2><button class="text-btn" data-view="accounts">Manage accounts ${icon('arrow')}</button></div>${filters()}<div id="account-grid" class="accounts-grid">${accountCards()}</div></section><div class="bottom-grid"><section class="panel"><div class="section-heading"><h2>Coming up</h2><button class="text-btn" data-view="schedule">View all ${icon('arrow')}</button></div>${nextEvents().slice(0,3).map(eventRow).join('')||'<p class="help">Your upcoming resets and renewals will appear here.</p>'}</section><section class="panel"><div class="section-heading"><h2>A little more breathing room</h2>${icon('spark')}</div><p class="help">Use accounts with near-term resets first, and make the most of a trial before it ends. Your weekly limit can still be the bottleneck, even with a full session window.</p><div class="list-row"><div class="provider-icon" style="--provider:var(--accent)">${icon('shield')}</div><div class="list-info"><strong>Private, by default</strong><p>Keep data on this device, export a backup, or enable optional Google Drive sync in Settings.</p></div></div><button class="text-btn" style="margin-top:13px" data-view="recommend">Find the best account ${icon('arrow')}</button></section></div>`;
}
function hero(){const best=rankAccounts(state.accounts)[0];return `<section class="hero"><div class="hero-content"><p class="eyebrow">${icon('spark')} YOUR NEXT BEST MOVE</p><h2>${best?`A good time to use ${esc(best.account.provider)}.`:'Your next idea deserves some room.'}</h2><p>${best?`${esc(best.account.name)} · ${best.reasons.slice(0,3).map(esc).join(' · ')}.`:'Add your accounts and usage limits to see a recommendation here.'}</p><div class="hero-actions">${best?`<button class="btn primary small" data-action="open-provider" data-id="${esc(best.account.id)}">Open ${esc(best.account.provider)} ${icon('arrow')}</button>`:addButton}<button class="text-btn" data-view="recommend">${best?'Why this account?':'How recommendations work'} ${icon('arrow')}</button></div></div><div class="hero-art" aria-hidden="true"><div class="planet"></div><div class="orbit-dot"></div><div class="orbit-dot"></div></div></section>`;}
function filters(){return `<div class="filters"><div class="chips" role="group" aria-label="Filter accounts">${['All accounts','Claude','ChatGPT','Codex','Gemini','Other'].map(f=>`<button class="chip ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search" type="search" value="${esc(query)}" placeholder="Find an account…" aria-label="Find an account"></label></div>`;}
function accountsPage(){return `${filters()}<div class="accounts-grid" id="account-grid">${accountCards()}</div><p class="help">Usage is manually recorded. Keep shared limits (for example, products on one subscription) in mind; Orbit does not infer shared billing or quotas.</p>`;}
function accountCards(){const accounts=state.accounts.filter(a=>(filter==='All accounts'||a.provider===filter)&&`${a.name} ${a.email} ${a.tier} ${a.provider}`.toLowerCase().includes(query.toLowerCase()));return accounts.map(accountCard).join('')||empty('Room for your AI accounts',state.accounts.length?'No accounts match this filter. Try another provider or search.':'Add an account and record its limits to begin.',addButton);}
function accountCard(a){
 const expired=isExpired(a),due=a.windows.some(w=>isDue(w));
 return `<article class="account ${a.paused?'paused':''}" style="--provider:${PROVIDERS[a.provider].color}"><div class="account-top">${providerIcon(a)}<div class="account-heading"><h3>${esc(a.provider)} <span class="badge ${a.status==='Trial'?'trial':'neutral'}">${esc(a.tier||a.status)}</span></h3><p>${esc(a.name)}${a.email?' · '+esc(a.email):''}</p></div><button class="icon-btn" data-action="favorite" data-id="${esc(a.id)}" aria-label="${a.favorite?'Unfavorite':'Favorite'} ${esc(a.name)}" style="${a.favorite?'color:var(--accent)':''}">${icon('star')}</button><button class="icon-btn" data-action="edit" data-id="${esc(a.id)}" aria-label="Edit ${esc(a.name)}">${icon('edit')}</button></div><div class="account-info"><span class="badge ${expired?'error':due?'warning':a.paused?'neutral':available(a)?'':'warning'}">${a.paused?'Paused':expired?'Expired':due?'Reset due · verify':available(a)?'Available':a.windows.length?'Limit reached':'Usage unknown'}</span><span class="badge ${a.status==='Trial'?'trial':'neutral'}">${a.status}${a.expiresAt?' · '+(expired?'ended':countdown(a.expiresAt)+' left'):''}</span></div>${a.windows.map(w=>`<div class="limit"><div class="limit-label"><span>${esc(w.label)} <span class="muted">· ${w.hours===168?'weekly':w.hours+'h'}</span></span><b>${Math.round(percent(w))}% used</b></div><div class="bar" role="meter" aria-label="${esc(w.label)} used" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(percent(w))}"><span class="${percent(w)>=100?'full':percent(w)>=80?'high':''}" style="--progress:${percent(w)}%"></span></div><div class="limit-meta"><span>${(w.limit-w.used).toLocaleString()} ${esc(w.unit)} left${resetCount(a,w)!==null?' · '+resetCount(a,w)+' resets before expiry':''}</span><span>${icon('clock')} ${w.nextReset?`${w.mode==='rolling'?'Est. ':'Resets '}${timer(w.nextReset)}`:'Reset not set'}</span></div></div>`).join('')||'<p class="help">Add a usage window to track capacity.</p>'}<div class="account-footer"><span>${a.status==='Trial'?'Trial ends':a.autoRenew?'Renews':'Billing date'} ${formatDate(a.status==='Trial'?a.expiresAt:a.renewAt)}</span><button class="text-btn" data-action="usage" data-id="${esc(a.id)}">Update usage ${icon('arrow')}</button></div><div class="footer-source">${icon('info')} Manual entry · checked ${formatDate(a.updatedAt)} at ${time(a.updatedAt)}</div></article>`;
}
function eventRow(e){return `<div class="list-row">${providerIcon(e.a)}<div class="list-info"><strong>${esc(e.a.provider)} <span class="muted">· ${esc(e.a.name)}</span></strong><p>${esc(e.label)}</p></div><div class="list-value">${timer(e.date)}<small>${formatDate(e.date)}</small></div></div>`;}
function recommendPage(){const ranked=rankAccounts(state.accounts,task);return `<div class="notice">Suggestions use your recorded capacity, task fit, favorites, and upcoming resets or expiry. Paused, expired, exhausted, and unverified reset accounts are excluded. Usage older than 24 hours lowers the score.</div><div class="section-heading"><h2>Choose your focus</h2><select id="task-select" aria-label="Task preference">${['All work','Coding','Writing','Research','General'].map(t=>`<option ${task===t?'selected':''}>${t}</option>`).join('')}</select></div><div>${ranked.map(({account:a,reasons},i)=>`<article class="rank-row"><div class="rank-number">${String(i+1).padStart(2,'0')}</div>${providerIcon(a)}<div class="list-info"><strong>${esc(a.provider)} · ${esc(a.name)} ${i===0?'<span class="badge">Best fit</span>':''}</strong><div class="rank-reasons">${reasons.map(esc).join(' · ')}</div></div><div class="rank-capacity">${Math.round(remaining(a))}%<small>tightest limit left</small></div><button class="btn small" data-action="open-provider" data-id="${esc(a.id)}">Open ${icon('arrow')}</button></article>`).join('')||empty('Let’s get an account ready','Add a usage limit or confirm an account’s current capacity to receive a recommendation.',`<button class="btn primary" data-view="accounts">Review accounts</button>`)}</div><p class="help" style="margin-top:22px">These are availability suggestions, not model-quality benchmarks. Opening a provider uses its current browser sign-in; switch to the account label shown here yourself.</p>`;}
function schedulePage(){const events=nextEvents();let prev='';return `<div class="notice">All times use your device timezone (${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}). Fixed-window counts are projections. Rolling reset times are estimates, and replenishment always needs confirmation.</div>${events.map(e=>{const group=Date.parse(e.date)<Date.now()?'Needs attention':formatDate(e.date);const heading=prev!==group?`<h3 class="timeline-group">${group}</h3>`:'';prev=group;return `${heading}<article class="event"><div class="event-time">${time(e.date)}<small>${timer(e.date)}</small></div>${providerIcon(e.a)}<div class="list-info"><strong>${esc(e.a.provider)} · ${esc(e.a.name)}</strong><p>${esc(e.label)} — ${esc(e.desc)}</p></div><button class="btn small" data-action="${e.type==='reset'?'usage':'edit'}" data-id="${esc(e.a.id)}">${e.type==='reset'?'Check usage':'Review'}</button></article>`;}).join('')||empty('A little space on your calendar','Add reset, renewal, or expiry dates to see them here.',addButton)}`;}
function historyPage(){return `<section class="panel"><div class="section-heading"><h2>Recent activity</h2><span class="muted" style="font-size:11px">${state.history.length} events</span></div>${state.history.map(e=>`<div class="list-row"><div class="history-dot"></div><div class="list-info"><strong>${esc(e.text)}</strong><p>${formatDate(e.at)} · ${time(e.at)}</p></div></div>`).join('')||empty('A fresh start','Account edits, reset confirmations, and usage updates will appear here.')}</section>`;}
function settingsPage(){return `<section class="panel" style="margin-bottom:22px"><div class="section-heading"><div><h2>Getting started</h2><p>Your startup guide is always here when you need it.</p></div><button class="btn primary" data-action="setup">Startup setup</button></div><button class="text-btn" data-view="guide">Read the complete guide →</button></section><section id="google-sync" class="panel sync-panel"></section><div class="settings-grid"><section class="panel"><h3>Backup & move your data</h3><p>Export an unencrypted JSON backup, then import it on another device. Backups include account labels, usage, notes, and activity.</p><div class="stack"><button class="btn" data-action="export">Export workspace</button><button class="btn" data-action="import">Import backup</button><button class="btn" data-action="sync-recovery">Export pre-sync recovery copy</button>${storageError?'<button class="btn" data-action="recovery">Download original saved data</button>':''}</div></section><section class="panel"><h3>On all your screens</h3><p>The web app works offline after its first successful online load. Install from your browser on desktop or Android. On iPhone, use Safari → Share → Add to Home Screen. Native apps bundle the interface for offline use.</p><button class="btn primary" data-action="install">Install Orbit</button><p style="margin:14px 0 0;font-size:11px" id="offline-status">${location.protocol==='file:'?'Desktop bundle · available offline':'Offline cache preparing…'}</p></section><section class="panel"><h3>Your workspace preferences</h3><p>${esc(preferences.workspaceName)} · Default currency: ${preferences.currency}. Reopen startup setup to change your workspace name and currency.</p><button class="btn" data-action="theme">Switch appearance</button><button class="btn" data-action="persist-storage" style="margin-top:10px">Request persistent browser storage</button><p style="margin-top:16px">No AI account passwords or analytics are collected. Usage updates are manual. Orbit cannot send alerts when it is closed.</p></section><section class="panel"><h3>Manage local data</h3><p>Your real accounts start here. Clearing this workspace removes its accounts and activity. Export a backup first. If Google auto-sync is enabled, clearing can sync to your other devices; earlier cloud versions remain.</p><button class="btn danger" data-action="clear">Clear personal workspace…</button></section></div>`;}
function gettingStarted(){return `<section class="getting-started"><p class="eyebrow">YOUR WORKSPACE IS READY</p><h2>Let’s add your first account.</h2><p>Start with a provider and plan, then copy its usage limits and reset times. You can also restore an existing backup. No sample balances are included.</p><div class="sync-actions">${addButton}<button class="btn" data-action="import">Restore a backup</button><button class="btn ghost" data-view="guide">Read the setup guide</button></div></section>`;}
function showSetup(){openSetup({preferences,onFinish:(next,action)=>{
 if(storageError)throw Error('Recover your saved data before changing setup.');
 localStorage.setItem(KEY,JSON.stringify(state));
 localStorage.setItem(PREFS_KEY,JSON.stringify(next));
 preferences=next;localStorage.setItem('orbit.theme',next.theme);document.body.classList.toggle('light',next.theme==='light');
 view='dashboard';render();
 setTimeout(()=>{if(action==='finish-add')editAccount();else if(action==='finish-import')$('#import-file').click();},0);
}});}

function openModal(html){$('#modal').innerHTML=html;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function modalHeader(title){return `<div class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;}
const localDate=iso=>{if(!iso)return '';const d=new Date(iso);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const options=(arr,selected)=>arr.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('');
function windowFields(w={},index=0){return `<div class="window-form" data-window-id="${esc(w.id||uid())}"><div class="window-top"><span>USAGE WINDOW</span><button type="button" class="icon-btn" data-action="remove-window" aria-label="Remove usage window">${icon('close')}</button></div><div class="form-grid"><label class="field">Window label<input name="w-label" value="${esc(w.label||'Session limit')}" maxlength="80" required></label><label class="field">Period in hours<input name="w-hours" type="number" min="0.25" max="8760" step="0.25" value="${w.hours||5}" required><small>5 = session · 24 = daily · 168 = weekly</small></label><label class="field">Total limit<input name="w-limit" type="number" min="0.01" step="any" value="${w.limit||100}" required></label><label class="field">Currently used<input name="w-used" type="number" min="0" step="any" value="${w.used||0}" required></label><label class="field">Units<input name="w-unit" value="${esc(w.unit||'%')}" maxlength="30" required><small>%, messages, credits, or tokens</small></label><label class="field">Reset behavior<select name="w-mode">${options(['fixed','rolling'],w.mode||'fixed')}</select></label><label class="field full">Next reset (local time)<input name="w-reset" type="datetime-local" value="${localDate(w.nextReset)}"><small>Use the provider’s displayed reset time. Rolling windows are estimates.</small></label></div></div>`;}
function editAccount(id){
 editingId=id||null;
 const a=state.accounts.find(a=>a.id===id)||{provider:'Claude',name:'',email:'',tier:'',status:'Paid',cost:0,currency:preferences.currency,billing:'monthly',windows:[],tasks:['General'],autoRenew:true};
 openModal(`<form id="account-form">${modalHeader(id?'Edit account':'Add your account')}<div class="modal-body"><div class="form-grid"><label class="field">Provider<select name="provider">${options(Object.keys(PROVIDERS),a.provider)}</select></label><label class="field">Account label<input name="name" placeholder="Personal, Work, Creative…" maxlength="80" value="${esc(a.name)}" required></label><label class="field">Email / identifier (optional)<input name="email" maxlength="200" value="${esc(a.email)}" placeholder="A label, not your password"></label><label class="field">Plan / tier<input name="tier" maxlength="80" value="${esc(a.tier)}" placeholder="Pro, Plus, Max, Free…"></label><label class="field">Subscription status<select name="status">${options(['Paid','Trial','Free'],a.status)}</select></label><label class="field">Billing cycle<select name="billing">${options(['monthly','yearly'],a.billing)}</select></label><label class="field">Price per billing cycle<input name="cost" type="number" min="0" step="0.01" value="${a.cost}" required></label><label class="field">Currency<select name="currency">${options(['USD','INR','EUR','GBP'],a.currency)}</select></label><label class="field">Next renewal / billing date<input name="renewAt" type="datetime-local" value="${localDate(a.renewAt)}"></label><label class="field">Trial / access expires<input name="expiresAt" type="datetime-local" value="${localDate(a.expiresAt)}"></label></div><div class="checks"><label><input type="checkbox" name="autoRenew" ${a.autoRenew?'checked':''}>Auto-renews</label><label><input type="checkbox" name="favorite" ${a.favorite?'checked':''}>Favorite</label><label><input type="checkbox" name="paused" ${a.paused?'checked':''}>Paused</label></div><div class="form-section">Best for</div><div class="checks">${['General','Coding','Writing','Research'].map(t=>`<label><input type="checkbox" name="tasks" value="${t}" ${a.tasks.includes(t)?'checked':''}>${t}</label>`).join('')}</div><div class="form-section">Usage windows <button type="button" class="btn small" data-action="add-window">${icon('plus')} Add limit</button></div><p class="help" style="margin-bottom:14px">Track session and weekly limits independently. The tightest remaining limit determines availability. No window means unknown usage.</p><div id="window-fields">${a.windows.map(windowFields).join('')}</div><label class="field full">Notes<textarea name="notes" maxlength="2000" placeholder="Shared subscription, model-specific limits, renewal reminder…">${esc(a.notes||'')}</textarea></label><p id="form-error" class="form-error" role="alert"></p></div><div class="modal-footer">${id?`<button type="button" class="btn danger" data-action="delete" data-id="${esc(id)}">Delete</button><span class="spacer"></span>`:''}<button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">Save account</button></div></form>`);
}
function usageModal(id){const a=state.accounts.find(a=>a.id===id);if(!a)return;editingId=id;openModal(`<form id="usage-form">${modalHeader('Update '+esc(a.provider)+' usage')}<div class="modal-body"><p class="help" style="margin-bottom:20px">${esc(a.name)} · Record what your provider shows. “Confirm reset” clears only that window and advances its timer.</p>${a.windows.map(w=>`<div class="window-form"><div class="section-heading"><h2>${esc(w.label)}</h2><span class="badge neutral">${w.hours}h · ${w.mode}</span></div><div class="form-grid"><label class="field">Used out of ${w.limit} ${esc(w.unit)}<input name="used-${esc(w.id)}" type="number" min="0" max="${w.limit}" step="any" value="${w.used}" required></label><label class="field">Next reset<input name="reset-${esc(w.id)}" type="datetime-local" value="${localDate(w.nextReset)}"></label></div><button type="button" class="text-btn" data-action="confirm-reset" data-window="${esc(w.id)}" style="margin-top:12px">${icon('check')} Confirm reset · set used to 0</button></div>`).join('')||'<p class="help">Add a usage window in the account editor first.</p>'}<p class="form-error" id="form-error" role="alert"></p></div><div class="modal-footer"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary">Save usage</button></div></form>`);}
function confirmModal(title,desc,action,id=''){openModal(`${modalHeader(title)}<div class="modal-body"><p class="help">${desc}</p></div><div class="modal-footer"><button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="${action}" data-id="${esc(id)}">Confirm</button></div>`);}
async function download(content,name){if(isNative()){await shareBackup(content,name);return;}const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action],[data-view],[data-filter]');if(!el)return;e.preventDefault();
 if(el.dataset.view){view=el.dataset.view;render();window.scrollTo(0,0);if(view==='settings')cacheStatus();return;}
 if(el.dataset.filter){filter=el.dataset.filter;render();return;}
 const a=state.accounts.find(a=>a.id===el.dataset.id);
 switch(el.dataset.action){
 case 'add':editAccount();break;
 case 'edit':editAccount(el.dataset.id);break;
 case 'usage':usageModal(el.dataset.id);break;
 case 'close':closeModal();break;
 case 'setup':showSetup();break;
 case 'favorite':if(a){a.favorite=!a.favorite;commit(`${a.name} ${a.favorite?'added to':'removed from'} favorites`);}break;
 case 'add-window':if($('#window-fields').children.length>=8){toast('You can track up to eight windows per account.');break;}$('#window-fields').insertAdjacentHTML('beforeend',windowFields());break;
 case 'remove-window':el.closest('.window-form').remove();break;
 case 'delete':confirmModal('Delete this account?',`${esc(a.name)} and its usage windows will be removed from this workspace. Your activity history will remain.`,'delete-confirm',a.id);break;
 case 'delete-confirm':state.accounts=state.accounts.filter(x=>x.id!==a.id);closeModal();commit(`Deleted ${a.name}`);break;
 case 'confirm-reset':{const account=state.accounts.find(x=>x.id===editingId);const w=account.windows.find(w=>w.id===el.dataset.window);const form=$('#usage-form');form.elements['used-'+w.id].value=0;form.elements['reset-'+w.id].value=localDate(advanceReset(w));el.textContent='Reset recorded — save usage to apply';el.dataset.confirmed='true';break;}
 case 'open-provider':if(a&&PROVIDERS[a.provider].url){try{await openProvider(PROVIDERS[a.provider].url);toast(`Open ${a.name} in ${a.provider}; check that the correct account is signed in.`);}catch{toast('Could not open the provider. Try opening it in your browser.');}}else toast('No provider link is configured for this custom account.');break;
 case 'theme':document.body.classList.toggle('light');try{preferences.theme=document.body.classList.contains('light')?'light':'dark';localStorage.setItem('orbit.theme',preferences.theme);localStorage.setItem(PREFS_KEY,JSON.stringify(preferences));}catch{}break;
 case 'export':try{await download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),`orbit-${''}${new Date().toISOString().slice(0,10)}.json`);toast('Backup exported. Keep it somewhere safe.');}catch{toast('Export was cancelled or could not finish. Your data is unchanged.');}break;
 case 'sync-recovery':{const saved=localStorage.getItem('orbit.sync.recovery');if(saved)await download(saved,'orbit-pre-sync-recovery.json');else toast('No cloud version has replaced your local workspace yet.');break;}
 case 'recovery':download(localStorage.getItem(KEY)||'','orbit-recovery.json');break;
 case 'import':$('#import-file').click();break;
 case 'import-confirm':state=pendingImport;storageError='';pendingImport=null;closeModal();commit('Imported workspace backup');break;
 case 'clear':confirmModal('Clear this workspace?','All accounts and activity in this workspace will be removed. Export a backup first. If Google auto-sync is enabled, this change can sync to your other devices.','clear-confirm');break;
 case 'clear-confirm':state={version:1,demo:false,accounts:[],history:[]};storageError='';persist();closeModal();render();toast('Workspace cleared.');break;
 case 'install':if(installPrompt){await installPrompt.prompt();const choice=await installPrompt.userChoice;toast(choice.outcome==='accepted'?'Orbit installed.':'You can install later from your browser menu.');installPrompt=null;}else{confirmModal('Install Orbit','On Chrome or Edge, use the address bar install icon or the browser’s “Install app” menu. On iPhone or iPad, open in Safari, then Share → Add to Home Screen. If already installed, open Orbit from your apps.','close');}break;
 case 'persist-storage':{const granted=await navigator.storage?.persist?.();toast(granted?'Persistent browser storage granted. Keep backups too.':'Storage remains browser-managed. Keep regular backups.');break;}
 }
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#account-grid').innerHTML=accountCards();}});
document.addEventListener('change',e=>{if(e.target.id==='task-select'){task=e.target.value;render();}});
document.addEventListener('submit',e=>{
 if(!['account-form','usage-form'].includes(e.target.id))return;e.preventDefault();const form=e.target;
 try{
  if(form.id==='account-form'){
   const fd=new FormData(form),previous=state.accounts.find(a=>a.id===editingId);
   const date=name=>fd.get(name)?new Date(fd.get(name)).toISOString():null;
   const a={id:editingId||uid(),provider:fd.get('provider'),name:fd.get('name').trim(),email:fd.get('email').trim(),tier:fd.get('tier').trim(),status:fd.get('status'),billing:fd.get('billing'),cost:Number(fd.get('cost')),currency:fd.get('currency'),renewAt:date('renewAt'),expiresAt:date('expiresAt'),autoRenew:fd.has('autoRenew'),favorite:fd.has('favorite'),paused:fd.has('paused'),tasks:fd.getAll('tasks'),notes:fd.get('notes'),updatedAt:new Date().toISOString(),windows:[...form.querySelectorAll('.window-form')].map(el=>{const v=name=>el.querySelector(`[name="w-${name}"]`).value;return {id:el.dataset.windowId,label:v('label').trim(),limit:Number(v('limit')),used:Number(v('used')),unit:v('unit'),hours:Number(v('hours')),mode:v('mode'),nextReset:v('reset')?new Date(v('reset')).toISOString():null};})};
   if(previous&&a.windows.length===previous.windows.length&&a.windows.every(w=>previous.windows.some(p=>p.id===w.id&&p.used===w.used&&p.limit===w.limit)))a.updatedAt=previous.updatedAt;
   validateAccount(a);
   if(previous)state.accounts=state.accounts.map(x=>x.id===a.id?a:x);else state.accounts.push(a);
   closeModal();commit(`${previous?'Updated':'Added'} ${a.provider} · ${a.name}`);
  }else{
   const original=state.accounts.find(a=>a.id===editingId),a=structuredClone(original);
   for(const w of a.windows){w.used=Number(form.elements['used-'+w.id].value);const date=form.elements['reset-'+w.id].value;w.nextReset=date?new Date(date).toISOString():null;}
   a.updatedAt=new Date().toISOString();validateAccount(a);
   const confirmed=form.querySelectorAll('[data-confirmed=true]').length;
   state.accounts=state.accounts.map(x=>x.id===a.id?a:x);closeModal();commit(`${a.name}: usage updated${confirmed?`, ${confirmed} reset${confirmed===1?'':'s'} confirmed`:''}`);
  }
 }catch(error){$('#form-error').textContent=error.message;}
});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('Backup must be smaller than 5 MB.');pendingImport=validateBackup(JSON.parse(await file.text()));confirmModal('Replace workspace with backup?',`This backup contains ${pendingImport.accounts.length} accounts and ${pendingImport.history.length} activity events. Import replaces your personal workspace. Export it first if you want to keep a copy.`,'import-confirm');}catch(error){toast(error.message);}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('online',()=>{$('#network-label').textContent='Local workspace';});
window.addEventListener('offline',()=>{$('#network-label').textContent='Working offline';});
window.addEventListener('storage',e=>{if(e.key===KEY&&!state.demo){if($('#modal').open){toast('Workspace changed in another tab. Reopen this editor before saving.');closeModal();}try{state=e.newValue?validateBackup(JSON.parse(e.newValue)):{version:1,demo:false,accounts:[],history:[]};render();}catch{toast('Could not load changes from the other tab.');}}});
async function cacheStatus(){const el=$('#offline-status');if(!el)return;if(location.protocol==='file:'){el.textContent='Desktop bundle · available offline';return;}try{const keys=await caches.keys();el.textContent=keys.some(k=>k.startsWith('orbit-'))?'Offline app cached · ready for travel':'Open online once to finish offline setup.';}catch{el.textContent='Offline cache unavailable in this environment.';}}
let signature='';
setInterval(()=>{document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=countdown(el.dataset.countdown));const next=state.accounts.map(a=>[isExpired(a),...a.windows.map(w=>isDue(w))].join()).join();if(signature&&next!==signature&&!$('#modal').open)render();signature=next;},1000);
const googleSync=setupGoogleSync({
 getLocal:()=>state,isNative,notify:toast,canApply:()=>!$('#modal').open&&!$('#setup-dialog').open&&!storageError,
 saveLocal:data=>{
  if(storageError)throw Error(storageError);
  const next=validateBackup(data);
  // Keep the previous personal workspace in case the selected cloud version was a mistake.
  localStorage.setItem('orbit.sync.recovery',JSON.stringify(state));
  localStorage.setItem(KEY,JSON.stringify(next));
  state=next;render();
 }
});
try{if(localStorage.getItem('orbit.theme')==='light')document.body.classList.add('light');}catch{}
render();
if(!storageError&&!preferences.setupComplete&&!state.accounts.length)showSetup();
if('serviceWorker' in navigator&&['http:','https:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').then(()=>cacheStatus()).catch(()=>{if($('#offline-status'))$('#offline-status').textContent='Offline cache unavailable; desktop builds still work offline.';});
